def _is_strict_mode(xs: list[int], v: int) -> bool:
    """Return True if v occurs in xs strictly more often than every other value."""
    return all((xs.count(v) > xs.count(w) for w in xs if w != v)) and v in xs

def _has_strict_mode(xs: list[int]) -> bool:
    """Return True if some value in xs occurs strictly more often than every other value."""
    return any((_is_strict_mode(xs, v) for v in xs))

def most_frequent(xs: list[int]) -> int | None:
    """Return the value that appears most often in xs, or None for an empty list.

    Assumes one value appears strictly more often than all others.
    pre: len(xs) == 0 or _has_strict_mode(xs)
    post: __return__ is None if len(xs) == 0 else _is_strict_mode(xs, __return__)
    """
    if not xs:
        return None
    counts: dict[int, int] = {}
    for x in xs:
        counts[x] = counts.get(x, 0) + 1
    return max(counts, key=counts.get)

